// Extract provenance from request metadata
const provenance = {
  source: 'UN Data API',
  sourceUrl: 'https://data.un.org/',
  retrievalDate: new Date().toISOString(),
  datasetCode: items[0].json.datasetCode,
  filterCode: items[0].json.filterCode,
  requestId: items[0].json.requestId || $execution.id,
  workflowId: $workflow.id,
  workflowName: $workflow.name,
  eventId: 'un_data_' + $execution.id + '_' + Date.now(),
  dataSource: 'public-api',
  accessMethod: 'api',
  proxyUsed: 'webshare',
  ingestionPipeline: 'harvy_pipeline_un_data',
  sink: 'harvy_sink_un_data'
};

// Add provenance to each item
for (const item of items) {
  item.json._provenance = provenance;
}

return items;

// Dedupe logic based on UN Data identifiers
const seen = new Set();
const dedupedItems = [];

for (const item of items) {
  const dedupeKey = item.json["Country or Area"] + "|" + item.json["Year"] + "|" + item.json["Value"];
  if (!seen.has(dedupeKey)) {
    seen.add(dedupeKey);
    dedupedItems.push(item);
  } else {
    // Log duplicate for monitoring
    item.json._duplicate = true;
    item.json._duplicateReason = 'Country/Year/Value combination already seen';
  }
}

return dedupedItems;

// Prepare data for Basin SQL ingestion
const preparedItems = items.map(item => ({
  country: item.json["Country or Area"],
  year: item.json["Year"],
  value: item.json["Value"],
  indicator: item.json["Indicator"],
  unit: item.json["Unit"],
  source: item.json._provenance.source,
  retrieval_date: item.json._provenance.retrievalDate,
  event_id: item.json._provenance.eventId,
  ingestion_timestamp: new Date().toISOString()
}));

return preparedItems;

// Log errors to harvy_errors table
const errorItems = items.filter(item => item.json._duplicate === true || item.json.error);
if (errorItems.length > 0) {
  const errors = errorItems.map(item => ({
    workflow_id: $workflow.id,
    workflow_name: $workflow.name,
    execution_id: $execution.id,
    error_type: item.json.error ? 'api_error' : 'duplicate_data',
    error_message: item.json.error || item.json._duplicateReason,
    source_dataset: 'un_data',
    record_identifier: item.json["Country or Area"] + '|' + item.json["Year"],
    severity: 'medium',
    timestamp: new Date().toISOString(),
    event_id: 'error_' + $execution.id + '_' + Date.now()
  }));

  // In a real workflow, this would insert into harvy_errors table
  console.log('ERRORS LOGGED:', JSON.stringify(errors, null, 2));
}

return items.filter(item => !item.json._duplicate);

// Add OpenObserve tracing headers
for (const item of items) {
  item.json._trace = {
    service: 'un_data_ingestion',
    version: '1.0.0',
    executionId: $execution.id,
    workflowId: $workflow.id,
    timestamp: new Date().toISOString(),
    source: 'n8n'
  };
}

return items;
